bounded_host_request.command:
set -eu
printf 'CREATEVDOBOT_DB_READONLY_STATUS\n'
docker exec -i gace-createvdobot-videobot-poll-1 node <<'GACE_NODE_DB_DIAG'
const fs=require('node:fs');
const pg=require('pg');
(async()=>{
 const e=process.env;
 const client=new pg.Client({host:e.VIDEOBOT_DB_HOST||'deploy-postgres-1',port:5432,database:e.VIDEOBOT_DB_NAME||'videobot',user:e.VIDEOBOT_DB_USER,password:fs.readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),connectionTimeoutMillis:5000});
 try{
  await client.connect();
  await client.query('BEGIN READ ONLY');
  for(const [label,sql,params] of [
   ['LISTING_STATUS',"SELECT status,count(*)::int AS n FROM videobot_listings GROUP BY status ORDER BY status",[]],
   ['RECEIPT_STATUS',"SELECT status,count(*)::int AS n FROM videobot_post_receipts GROUP BY status ORDER BY status",[]],
   ['SESSION_PUBLISHING',"SELECT coalesce(state->>'publishing','none') AS mode,count(*)::int AS n FROM videobot_creator_sessions GROUP BY 1 ORDER BY 1",[]],
   ['SESSION_EDITOR_MODE',"SELECT coalesce(state->'draft'->>'mode','none') AS mode,count(*)::int AS n FROM videobot_creator_sessions GROUP BY 1 ORDER BY 1",[]],
   ['NAMED_LISTING',"SELECT status,count(*)::int AS n FROM videobot_listings WHERE title=$1 GROUP BY status",['肉便器']]
  ]) {const q=await client.query(sql,params);console.log(label+'='+JSON.stringify(q.rows));}
  await client.query('ROLLBACK');
 }catch(err){console.log('DB_DIAG_ERROR='+String(err.code||err.message).slice(0,80));process.exitCode=43;}
 finally{await client.end().catch(()=>{});}
})();
GACE_NODE_DB_DIAG
